/**
 * Foreign key definitions: ALTER builders, validation, grouping of information_schema rows.
 * Ported from phpMyAdmin 5.2.3 Controllers/Table/RelationController.php and Table::getForeignKeys.
 */
import { quoteId } from './column-definition.ts';
import type { ParsedIndex } from './index-definition.ts';

/** '' = clause omitted (server default, same as RESTRICT / NO ACTION). */
export const FK_ACTIONS = ['', 'RESTRICT', 'CASCADE', 'SET NULL', 'NO ACTION'] as const;
export type FkAction = (typeof FK_ACTIONS)[number];

export interface FkDef {
	/** Constraint name; empty = generated by the server. */
	name: string;
	columns: string[];
	refDb: string;
	refTable: string;
	refColumns: string[];
	onDelete: FkAction;
	onUpdate: FkAction;
}

export function newFkDef(overrides: Partial<FkDef> = {}): FkDef {
	return {
		name: '',
		columns: [''],
		refDb: '',
		refTable: '',
		refColumns: [''],
		onDelete: '',
		onUpdate: '',
		...overrides
	};
}

const tableRef = (db: string, table: string): string => `${quoteId(db)}.${quoteId(table)}`;

export function validateFkDef(def: FkDef): string | null {
	if (def.columns.length === 0) return 'Choose at least one column.';
	if (def.columns.length !== def.refColumns.length) {
		return 'The number of columns and referenced columns must match.';
	}
	if (def.columns.some((c) => c === '') || def.refColumns.some((c) => c === '')) {
		return 'Choose a column and a referenced column for every pair.';
	}
	if (new Set(def.columns).size !== def.columns.length) return 'A column is used twice.';
	if (def.refDb === '' || def.refTable === '') return 'Choose the referenced table.';
	if (def.name.length > 64) return 'The constraint name is too long.';
	return null;
}

export function buildAddForeignKey(db: string, table: string, def: FkDef): string {
	let sql = `ALTER TABLE ${tableRef(db, table)}\n  ADD `;
	if (def.name !== '') sql += `CONSTRAINT ${quoteId(def.name)} `;
	sql += `FOREIGN KEY (${def.columns.map(quoteId).join(', ')}) `;
	sql += `REFERENCES ${tableRef(def.refDb, def.refTable)} (${def.refColumns.map(quoteId).join(', ')})`;
	if (def.onDelete !== '') sql += ` ON DELETE ${def.onDelete}`;
	if (def.onUpdate !== '') sql += ` ON UPDATE ${def.onUpdate}`;
	return sql + ';';
}

export function buildDropForeignKey(db: string, table: string, name: string): string {
	return `ALTER TABLE ${tableRef(db, table)} DROP FOREIGN KEY ${quoteId(name)};`;
}

/**
 * Do `columns` form the leading columns of some BTREE/HASH/UNIQUE index (in any order)? That is
 * what InnoDB requires of the referenced columns.
 */
export function columnsAreIndexed(columns: string[], indexes: ParsedIndex[]): boolean {
	const wanted = new Set(columns);
	return indexes.some((idx) => {
		if (idx.kind === 'FULLTEXT' || idx.kind === 'SPATIAL') return false;
		if (idx.columns.length < columns.length) return false;
		const lead = idx.columns.slice(0, columns.length).map((c) => c.name);
		return lead.every((n) => n !== null && wanted.has(n));
	});
}

export interface FkRow {
	constraintName: string;
	columnName: string;
	ordinal: number;
	refDb: string;
	refTable: string;
	refColumn: string;
	deleteRule: string;
	updateRule: string;
}

export function groupForeignKeys(rows: FkRow[]): FkDef[] {
	const map = new Map<string, FkDef>();
	for (const r of [...rows].sort((a, b) => a.ordinal - b.ordinal)) {
		let fk = map.get(r.constraintName);
		if (!fk) {
			const norm = (v: string): FkAction =>
				(FK_ACTIONS as readonly string[]).includes(v.toUpperCase())
					? (v.toUpperCase() as FkAction)
					: '';
			fk = {
				name: r.constraintName,
				columns: [],
				refDb: r.refDb,
				refTable: r.refTable,
				refColumns: [],
				onDelete: norm(r.deleteRule),
				onUpdate: norm(r.updateRule)
			};
			map.set(r.constraintName, fk);
		}
		fk.columns.push(r.columnName);
		fk.refColumns.push(r.refColumn);
	}
	return [...map.values()];
}

/** Engines that enforce foreign keys (Util::isForeignKeySupported). */
export const supportsForeignKeys = (engine: string | null): boolean =>
	engine !== null && /^(innodb|xtradb|pbxt)$/i.test(engine);
